```q
move_one_ball:{[x]
    if[not count[x];
        :1b;
    ];

    if[1 = count[x];
        :1b;
    ];

    n: count[x];
    sorted_x: asc[x];

    if[x ~ sorted_x;
        :1b;
    ];

    drop_count: 0;

    i: 0;

    while[i < n;
        if[not (x[i]) = sorted_x[i];
            drop_count: i;
            ];
        i: i + 1;
        ];

    if[drop_count = 0;
        :1b;
    ];

    rotated_x: (neg[drop_count] rotate x);

    if[rotated_x ~ sorted_x;
        :1b;
        ];

    :0b;
    };
