```q
do_algebra:{[operators;operands]
    result:operands[0];

    i:0;

    while[i < count[operators];
        op:operators[i];
        next_val:operands[i + 1];

        $[op ~ "+";
            result:result + next_val;
          op ~ "-";
            result:result - next_val;
          op ~ "*";
            result:result * next_val;
          op ~ "//";
            result:result div next_val;
          op ~ "**";
            result:result xexp next_val
        ];

        i:i + 1;
    ];

    :result;
    }
```

